package notification.core.recipient;import notification.core.recipient.Recipient;/** * Push notification recipient. */public class PushRecipient implements Recipient {    private final String deviceToken;    private final String language;    public PushRecipient(            String deviceToken,            String language) {        this.deviceToken = deviceToken;        this.language = language;    }    public String getDeviceToken() {        return deviceToken;    }    @Override    public String id() {        return deviceToken;    }    @Override    public String language() {        return language;    }}